const $ = s => document.querySelector(s);
const esc = s => String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let saved = {}; let storageOK = true;
try { saved = JSON.parse(localStorage.getItem('grammar-map-v1') || '{}') || {}; } catch { storageOK = false; }
const validIds = new Set(lessons.map(l=>l.id));
const state = {done:Array.isArray(saved.done)?saved.done.filter(x=>validIds.has(x)):[],bookmarks:Array.isArray(saved.bookmarks)?saved.bookmarks.filter(x=>validIds.has(x)):[],last:validIds.has(saved.last)?saved.last:'sentence'};
function persist(){try{localStorage.setItem('grammar-map-v1',JSON.stringify(state))}catch{storageOK=false; toast('浏览器无法保存进度，本次仍可正常学习。')}updateProgress()}
function toast(message){$('#toast').textContent=message;$('#toast').classList.add('show');clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),2600)}
function updateProgress(){const n=state.done.length;$('#progress-count').textContent=`${n} / ${lessons.length}`;$('#progress-bar').style.width=`${n/lessons.length*100}%`;$('#bookmark-count').textContent=state.bookmarks.length}
function chapterNav(){ $('#chapter-nav').innerHTML=chapters.map((c,i)=>`<a href="#chapter/${c.id}"><span class="chapter-number">0${i+1}</span><span>${c.name}</span><span class="nav-dot ${c.color}"></span></a>`).join('') }
function lessonRows(items){return items.map(l=>`<a class="lesson-row" href="#lesson/${l.id}"><span class="lesson-status ${state.done.includes(l.id)?'complete':''}">${state.done.includes(l.id)?'✓':String(lessons.indexOf(l)+1).padStart(2,'0')}</span><span><strong>${esc(l.title)}</strong><small>${esc(l.summary)}</small></span><span class="row-arrow">↗</span></a>`).join('')}
function renderHome(){const next=lessons.find(l=>!state.done.includes(l.id))||lessons[0];$('#main').innerHTML=`
 <section class="hero"><div class="hero-copy"><div class="eyebrow"><span></span> 从零开始，也可以学得明白</div><h1>英语语法，<br>从<span class="hand-underline">一句话</span>开始。</h1><p>不用一上来就背规则。先看懂句子怎么搭起来，<br class="desktop">再把词、时间和想法，一点点放进去。</p><div class="hero-actions"><a class="button primary" href="#lesson/${next.id}">${state.done.length?'继续学习':'从第一课开始'} <span>↗</span></a><a class="quiet-link" href="#map">先看看整个体系 ↓</a></div><div class="hero-facts"><span>6 个学习章节</span><i></i><span>${lessons.length} 个语法主题</span><i></i><span>中文讲解 · 双语例句</span></div></div>
 <div class="hero-art" aria-label="英语句子由主语、动词和其他成分组合"><div class="art-top">A LITTLE GRAMMAR. A BIGGER WORLD.<span>✳</span></div><div class="art-sentence"><span class="word subject">I<small>谁 · 主语</small></span><span class="word verb">build<small>做什么 · 谓语</small></span><span class="word object">things.<small>什么 · 宾语</small></span></div><div class="art-line"><span>我</span><span>创造</span><span>事物。</span></div><div class="art-note"><span class="note-arrow">↳</span> 一个想法，就从这里长出来。</div><div class="art-bottom"><span>SUBJECT + VERB + OBJECT</span><span>01 / ${lessons.length}</span></div></div></section>
 <section class="start-note"><div class="note-symbol">✦</div><div><strong>语法是一张地图，不是一张考卷。</strong><p>按顺序学，或者从困扰你的问题开始。每一节都有解释、例句和一道小练习。</p></div><a href="#lesson/sentence">认识第一句话 <span>→</span></a></section>
 <section id="map" class="map-section"><div class="section-heading"><div><div class="eyebrow">YOUR GRAMMAR MAP</div><h2>把整个体系，慢慢连起来<span>。</span></h2></div><span class="subtle">从简单句，到完整表达</span></div><div class="chapter-grid">${chapters.map((c,i)=>{const group=lessons.filter(l=>l.chapter===i);return `<a href="#chapter/${c.id}" class="chapter-card ${c.color}"><div class="card-top"><span class="chapter-icon">${c.icon}</span><span class="card-index">CHAPTER 0${i+1}</span></div><div class="card-level">${c.level}</div><h3>${c.name}</h3><p>${c.desc}</p><div class="topic-tags">${group.slice(0,3).map(l=>`<span>${l.title.split('：')[0].replace('一句话是怎么组成的？','句子结构').replace('a、an、the 怎么选？','冠词')}</span>`).join('')}</div><div class="card-footer"><span>${group.length} 个主题 · ${group.filter(l=>state.done.includes(l.id)).length} 已读</span><span class="circle-arrow">↗</span></div></a>`}).join('')}</div></section>
 <section class="bottom-banner"><span class="banner-mark">“</span><div><h3>会认规则，也要试着说一句。</h3><p>学完一个知识点，用自己的生活造个句子：今天做了什么，明天想去哪里。</p></div><a href="#lesson/present">试试一般现在时 →</a></section>`}
function renderChapter(id){const i=chapters.findIndex(c=>c.id===id);if(i<0)return notFound();const c=chapters[i];$('#breadcrumb').textContent=c.name;$('#main').innerHTML=`<div class="reading-wrap"><a class="back-link" href="#">← 返回语法地图</a><div class="eyebrow">CHAPTER 0${i+1} · ${c.en}</div><h1 class="page-title">${c.name}<span>。</span></h1><p class="page-lead">${c.desc} 按顺序学习，或者选择你想了解的主题。</p><div class="chapter-lessons">${lessonRows(lessons.filter(l=>l.chapter===i))}</div><div class="tip"><strong>怎么学这一章？</strong><p>先读解释和例句，再用自己的话造句。练习选对不代表已经掌握，下次遇到真实句子时再验证一次。</p></div></div>`}
function tenseTable(){return `<section class="lesson-section"><h2>看一眼：时间与状态的地图</h2><p>这张表用于定位，不需要一次背完。先学一般现在、一般过去、现在进行、现在完成和常见将来表达。完成进行强调持续的过程；过去完成把参照点放在过去，将来完成把参照点放在将来。</p><div class="table-scroll"><table><caption>教学中常见的十二种时间与状态组合</caption><thead><tr><th>时间视角</th><th>一般</th><th>进行</th><th>完成</th><th>完成进行</th></tr></thead><tbody>${tenseGrid.map(row=>`<tr>${row.map((v,i)=>`<${i?'td':'th'}>${esc(v)}</${i?'td':'th'}>`).join('')}</tr>`).join('')}</tbody></table></div><p class="caption">将来表达并非独立的动词时态词形；这是一种方便入门的教学分类。</p></section>`}
function renderLesson(id){const l=lessons.find(x=>x.id===id);if(!l)return notFound();state.last=id;persist();const n=lessons.indexOf(l),c=chapters[l.chapter];$('#breadcrumb').textContent=l.title;$('#main').innerHTML=`<div class="lesson-layout"><article class="lesson-content"><a class="back-link" href="#chapter/${c.id}">← ${c.name}</a><div class="lesson-title-meta"><span class="eyebrow">CHAPTER 0${l.chapter+1} · LESSON ${String(n+1).padStart(2,'0')}</span><button id="bookmark" class="bookmark-button" aria-pressed="${state.bookmarks.includes(id)}">${state.bookmarks.includes(id)?'★ 已收藏':'☆ 收藏本节'}</button></div><h1 class="page-title">${l.title}</h1><p class="english-title">${l.en}</p><p class="lesson-summary">${l.summary}</p>
 <section class="lesson-section" id="understand"><h2><span>01</span> 先用大白话理解</h2><p>${l.explain}</p><div class="pattern"><span>记住这个结构</span><strong>${l.pattern}</strong></div></section>
 ${id==='sentence'?`<div class="sentence-builder"><span>拆开看，就清楚了</span><div><button data-part="subject">I<small>主语</small></button><button data-part="verb">write<small>谓语动词</small></button><button data-part="object">code.<small>宾语</small></button></div><p id="part-explanation" aria-live="polite">点一下上面的词，看看它在句子里做什么。</p></div>`:''}
 <section class="lesson-section" id="examples"><h2><span>02</span> 放进句子里看看</h2><div class="examples">${l.examples.map((e,i)=>`<div class="example"><span class="example-number">0${i+1}</span><div><p class="english-example" lang="en">${esc(e[0])}</p><p class="translation">${e[1]}</p><p class="example-detail">${e[2]}</p></div></div>`).join('')}</div></section>
 ${id==='future'?tenseTable():''}<div class="tip" id="tip"><strong>↳ 一个容易踩的坑</strong><p>${l.tip}</p></div>
 <section class="lesson-section quiz" id="practice"><div class="eyebrow">A LITTLE PRACTICE</div><h2>用一道题，确认一下。</h2><p class="quiz-question">${l.quiz.q}</p><div class="quiz-options">${l.quiz.options.map((o,i)=>`<button class="quiz-option" data-answer="${i}"><span>${String.fromCharCode(65+i)}</span>${esc(o)}</button>`).join('')}</div><div id="quiz-feedback" role="status"></div></section>
 <section class="own-sentence"><h2>轮到你造一句。</h2><p>用本节结构写一句关于自己的话。这里只保存草稿，不会自动评判对错。</p><textarea id="sentence-draft" rows="3" placeholder="例如：I write code every day. 写下你自己的版本…" aria-label="我的造句草稿"></textarea><span id="draft-status" aria-live="polite">草稿保存在当前浏览器</span></section>
 <div class="lesson-end"><button class="button primary" id="complete">${state.done.includes(id)?'✓ 已读过本节':'标记已读 ✓'}</button><span>读过之后，还可以回来复习。</span></div><div class="lesson-pagination">${n?`<a href="#lesson/${lessons[n-1].id}"><small>← 上一节</small>${lessons[n-1].title}</a>`:'<span></span>'}${n<lessons.length-1?`<a href="#lesson/${lessons[n+1].id}"><small>下一节 →</small>${lessons[n+1].title}</a>`:'<a href="#"><small>完成浏览 →</small>回到语法地图</a>'}</div></article>
 <aside class="lesson-toc"><span class="side-label">这一节，慢慢看</span><a href="#understand" data-scroll="understand">01 大白话理解</a><a href="#examples" data-scroll="examples">02 双语例句</a><a href="#tip" data-scroll="tip">03 易错提醒</a><a href="#practice" data-scroll="practice">04 动手练习</a><div><span>✳</span><p>不必一次记住。<br>下次用到时，<br>再回来看看。</p></div></aside></div>`;
 $('#bookmark').onclick=()=>{state.bookmarks=state.bookmarks.includes(id)?state.bookmarks.filter(x=>x!==id):[...state.bookmarks,id];persist();const b=$('#bookmark');b.textContent=state.bookmarks.includes(id)?'★ 已收藏':'☆ 收藏本节';b.setAttribute('aria-pressed',String(state.bookmarks.includes(id)))};
 $('#complete').onclick=()=>{const done=state.done.includes(id);state.done=done?state.done.filter(x=>x!==id):[...state.done,id];persist();$('#complete').textContent=done?'标记已读 ✓':'✓ 已读过本节';toast(done?'已取消已读标记':'已记录，下一次继续向前。')};
 document.querySelectorAll('[data-answer]').forEach(b=>b.onclick=()=>{const choice=Number(b.dataset.answer),correct=choice===l.quiz.answer;document.querySelectorAll('[data-answer]').forEach(x=>{x.classList.remove('wrong','correct');x.setAttribute('aria-pressed','false')});b.classList.add(correct?'correct':'wrong');b.setAttribute('aria-pressed','true');$('#quiz-feedback').className=correct?'feedback correct':'feedback wrong';$('#quiz-feedback').textContent=correct?'✓ 选对了。'+l.quiz.why:'再想一想。'+l.quiz.why});
 const partText={subject:'I = 我。它是主语，告诉你“谁在做这件事”。',verb:'write = 写。它是谓语动词，告诉你主语“做什么”。',object:'code = 代码。它是宾语，告诉你“写的是什么”。'};
 document.querySelectorAll('[data-part]').forEach(b=>b.onclick=()=>{$('#part-explanation').textContent=partText[b.dataset.part]});
 document.querySelectorAll('[data-scroll]').forEach(a=>a.onclick=e=>{e.preventDefault();document.getElementById(a.dataset.scroll).scrollIntoView({behavior:'smooth',block:'start'})});
 try{$('#sentence-draft').value=localStorage.getItem('grammar-draft-'+id)||''}catch{};
 $('#sentence-draft').oninput=()=>{try{localStorage.setItem('grammar-draft-'+id,$('#sentence-draft').value);$('#draft-status').textContent='✓ 草稿已保存'}catch{$('#draft-status').textContent='无法保存，请自行复制草稿'}};
}
function renderReview(){$('#breadcrumb').textContent='我的收藏';$('#main').innerHTML=`<div class="reading-wrap"><div class="eyebrow">YOUR LITTLE COLLECTION</div><h1 class="page-title">值得再看一遍<span>。</span></h1><p class="page-lead">把暂时没弄懂的知识点留在这里，遇到真实句子时再回来。</p>${state.bookmarks.length?`<div class="chapter-lessons">${lessonRows(lessons.filter(l=>state.bookmarks.includes(l.id)))}</div>`:'<div class="empty-state"><span>☆</span><h2>还没有收藏的知识点</h2><p>打开任意课程，点“收藏本节”，就能在这里找到它。</p><a class="button primary" href="#">去语法地图看看 ↗</a></div>'}</div>`}
function renderReferences(){$('#breadcrumb').textContent='参考与说明';$('#main').innerHTML=`<div class="reading-wrap"><a class="back-link" href="#">← 返回地图</a><div class="eyebrow">ABOUT THIS HANDBOOK</div><h1 class="page-title">先理解，再慢慢深入。</h1><p class="page-lead">这是一份面向中文初学者的英语语法体系入门手册。</p><div class="prose"><h2>范围与学习顺序</h2><p>这里覆盖句子骨架、常见词类、动词时间表达、语态、句式、从句与非谓语等主要板块，提供体系概览与起步例句。它不是穷尽所有例外的参考语法书，也不等同于完整的英语能力课程。基础章节可按顺序学，进阶章节先知道“有这回事”即可。</p><h2>讲解与例句</h2><p>中文讲解与例句为本站编写。部分规则作了面向初学者的简化，并注明常见边界。遇到复杂语境，可继续查阅以下参考资料。</p><a class="source-link" target="_blank" rel="noopener noreferrer" href="https://learnenglish.britishcouncil.org/free-resources/grammar/english-grammar-reference">British Council · English grammar reference ↗</a><a class="source-link" target="_blank" rel="noopener noreferrer" href="https://learnenglish.britishcouncil.org/free-resources/grammar/a1-a2">British Council · A1–A2 grammar ↗</a><a class="source-link" target="_blank" rel="noopener noreferrer" href="https://dictionary.cambridge.org/grammar/british-grammar/">Cambridge Dictionary · English Grammar Today ↗</a><h2>关于学习记录</h2><p>已读、收藏和造句草稿仅保存在当前浏览器，不会跨设备同步。清理浏览器数据会清除这些记录。本站没有接入 AI，也不会将练习或草稿发送到服务器。</p></div></div>`}
function notFound(){$('#main').innerHTML='<div class="reading-wrap empty-state"><h1>这一页没有找到。</h1><a class="button primary" href="#">回到语法地图</a></div>'}
function render(){const hash=location.hash.slice(1);if(hash==='map'){$('#map')?.scrollIntoView({behavior:'smooth'});if(!$('#map')){renderHome();$('#map').scrollIntoView()}return}$('#breadcrumb').textContent='语法地图';const [type,id]=hash.split('/');document.querySelectorAll('.main-nav a').forEach(a=>a.classList.toggle('active',a.dataset.nav===(type==='review'?'review':type==='lesson'?'lesson':'home')));document.querySelectorAll('.chapter-nav a').forEach((a,i)=>a.classList.toggle('active',(type==='chapter'&&chapters[i].id===id)||(type==='lesson'&&lessons.find(l=>l.id===id)?.chapter===i)));if(type==='lesson')renderLesson(id);else if(type==='chapter')renderChapter(id);else if(type==='review')renderReview();else if(type==='references')renderReferences();else if(!hash)renderHome();else notFound();document.title=`${$('#breadcrumb').textContent} · 从句子开始`;document.body.classList.remove('menu-open');$('#menu-toggle').setAttribute('aria-expanded','false');window.scrollTo(0,0);updateProgress()}
function search(){const query=$('#search-input').value.trim().toLowerCase();const results=query?lessons.filter(l=>[l.title,l.en,l.summary,l.explain,l.pattern,...l.examples.flat()].join(' ').toLowerCase().includes(query)):lessons.slice(0,6);$('#search-results').innerHTML=`<p class="search-label">${query?`找到 ${results.length} 个相关主题`:'从这些知识点开始'}</p>${results.length?results.map(l=>`<a class="search-result" href="#lesson/${l.id}"><span><strong>${l.title}</strong><small>${l.en} · ${chapters[l.chapter].name}</small></span><span>↗</span></a>`).join(''):'<div class="search-empty">没有匹配结果。试试“时态”“名词”或英文名称。</div>'}`;document.querySelectorAll('.search-result').forEach(a=>a.onclick=()=>$('#search-dialog').close())}
function openSearch(){search();$('#search-dialog').showModal();$('#search-input').focus()}
$('#search-trigger').onclick=openSearch;$('#search-close').onclick=()=>$('#search-dialog').close();$('#search-input').oninput=search;$('#search-dialog').onclick=e=>{if(e.target===$('#search-dialog'))$('#search-dialog').close()};
document.addEventListener('keydown',e=>{if(e.key==='/'&&!['INPUT','TEXTAREA'].includes(document.activeElement.tagName)&&!$('#search-dialog').open){e.preventDefault();openSearch()}});
$('#menu-toggle').onclick=()=>{document.body.classList.toggle('menu-open');$('#menu-toggle').setAttribute('aria-expanded',String(document.body.classList.contains('menu-open')))};
window.addEventListener('hashchange',render);chapterNav();render();if(!storageOK)toast('当前浏览器的本地保存不可用。');
